from catalog import lookup

def breakdown(label, seats, savings_cents=0):
    plan = lookup(label)
    if type(seats) is not int or seats < 1 or seats > plan['max_seats']:
        raise ValueError('seats')
    subtotal = plan['seat_cents'] * seats
    if type(savings_cents) is not int or savings_cents < 0 or savings_cents > subtotal:
        raise ValueError('savings_cents')
    return {
        'plan_code': plan['code'],
        'subtotal_cents': subtotal,
        'savings_cents': savings_cents,
        'total_cents': subtotal - savings_cents,
    }


def quote(label, seats, savings_cents=0):
    return breakdown(label, seats, savings_cents)['total_cents']
